{
  "name": "Elveflow OB1‑Mk4 微流控压力控制器",
  "name_en": "Elveflow OB1-Mk4 microfluidic pressure controller",
  "manufacturer": "Elveflow",
  "description": "这是一款用于微流控实验的多通道压力控制器，可为芯片、储液器或流体回路提供精密气压驱动。设备可读取各压力通道数据，并可接入流量或压力传感器进行监测、校准与闭环 PID 控制，常用于稳定微流量输送、液滴生成和微流控芯片流路调节。",
  "description_en": "This device is a multi-channel pressure controller for microfluidic experiments, providing precise pneumatic actuation for chips, reservoirs, and fluidic circuits. It can read pressure on each channel and work with flow or pressure sensors for monitoring, calibration, and closed-loop PID control, making it suitable for stable low-flow delivery, droplet generation, and microfluidic flow regulation.",
  "tag_hints": [
    "microfluidics",
    "pressure control",
    "multi-channel pressure regulation",
    "flow sensing",
    "closed-loop PID control",
    "pneumatic actuation"
  ],
  "actions": [
    {
      "action_name": "auto-open",
      "description": "连接到压力控制器。",
      "description_en": "Open a connection to the pressure controller."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与压力控制器的连接。",
      "description_en": "Close the connection to the pressure controller."
    },
    {
      "action_name": "auto-loadDLL",
      "description": "加载访问控制器所需的厂商通信库。",
      "description_en": "Load the vendor communication library required to access the controller."
    },
    {
      "action_name": "auto-loadCallibration",
      "description": "加载压力通道的校准数据。",
      "description_en": "Load calibration data for the pressure channels."
    },
    {
      "action_name": "auto-performCallibration",
      "description": "执行压力通道校准并保存校准数据。",
      "description_en": "Perform calibration of the pressure channels and save the calibration data."
    },
    {
      "action_name": "auto-setPressure",
      "description": "设置指定通道的目标压力。",
      "description_en": "Set the target pressure for a specified channel."
    },
    {
      "action_name": "auto-getPressure",
      "description": "读取指定通道的压力。",
      "description_en": "Read the pressure of a specified channel."
    },
    {
      "action_name": "auto-addSensor",
      "description": "为指定通道添加并配置传感器。",
      "description_en": "Add and configure a sensor on a specified channel."
    },
    {
      "action_name": "auto-getSensorData",
      "description": "读取指定通道传感器的数据。",
      "description_en": "Read data from the sensor on a specified channel."
    },
    {
      "action_name": "auto-startRemote",
      "description": "启动远程运行模式并开始后台控制循环。",
      "description_en": "Start remote operation mode and begin the background control loop."
    },
    {
      "action_name": "auto-stopRemote",
      "description": "停止远程运行模式。",
      "description_en": "Stop remote operation mode."
    },
    {
      "action_name": "auto-remoteGetData",
      "description": "在远程模式下读取通道压力和传感器数据。",
      "description_en": "Read channel pressure and sensor data while in remote mode."
    },
    {
      "action_name": "auto-remoteSetTarget",
      "description": "在远程模式下设置指定通道的控制目标。",
      "description_en": "Set the control target for a specified channel in remote mode."
    },
    {
      "action_name": "auto-remoteAddPID",
      "description": "在压力通道与传感器之间建立 PID 闭环控制。",
      "description_en": "Configure a PID control loop between a pressure channel and a sensor."
    },
    {
      "action_name": "auto-remotePausePID",
      "description": "暂停指定通道的 PID 控制。",
      "description_en": "Pause PID control for a specified channel."
    },
    {
      "action_name": "auto-remoteStartPID",
      "description": "启动指定通道的 PID 控制。",
      "description_en": "Start PID control for a specified channel."
    },
    {
      "action_name": "auto-remoteResetPID",
      "description": "重置指定通道的 PID 控制状态。",
      "description_en": "Reset the PID control state for a specified channel."
    },
    {
      "action_name": "auto-remoteChangePID",
      "description": "修改指定通道的 PID 参数。",
      "description_en": "Change the PID parameters for a specified channel."
    },
    {
      "action_name": "auto-getPressureUniversal",
      "description": "读取指定通道的压力，不受当前运行模式影响。",
      "description_en": "Read the pressure of a specified channel regardless of the current operating mode."
    },
    {
      "action_name": "auto-getFlowUniversal",
      "description": "读取指定通道的流量传感器数据，不受当前运行模式影响。",
      "description_en": "Read flow sensor data for a specified channel regardless of the current operating mode."
    }
  ]
}

